export default '/**\n * Stackra file contract:\n * Purpose: the "edit-answers" demo of the native QuestionnaireCard: last week\'s answers to the sales report questions\n *          are filled in, so Next walks to the summary where one answer can be changed before the report is built.\n * Boundary: a demo with no props, @stackra/ui and local state only; the same file is the preview and the code shown.\n * Runtime: react-native\n * Governing contract: showcase redesign spec (2026-10-27) section 4 (demo contract); ADR 0302 (decision 3); ADR 0060;\n *          STA-1371 (wave D, owner approval 2026-10-30).\n */\nimport { QuestionnaireCard, Text, useCatalogueText } from "@stackra/ui/native";\nimport { useState } from "react";\nimport { View } from "react-native";\n\nimport { MESSAGES } from "#src/constants/messages.constant";\nimport { QUESTIONNAIRE_CARD_DEMO_KEYS } from "#src/demos/free/questionnaire-card/questionnaire-card-demo-keys.constant";\n\n/** The demo\'s keys. */\nconst K = QUESTIONNAIRE_CARD_DEMO_KEYS.demo_free.questionnaire_card.edit_answers;\n\n/** QuestionnaireCard: Edit earlier answers. */\nexport default function EditAnswers() {\n  const t = useCatalogueText(MESSAGES.en);\n  const periods = [\n    { value: "this_week", label: t(K.this_week) },\n    { value: "last_week", label: t(K.last_week) },\n    { value: "this_month", label: t(K.this_month) },\n  ];\n  const [period, setPeriod] = useState<string | null>(null);\n  return (\n    <View className="gap-3">\n      <QuestionnaireCard\n        title={t(K.title)}\n        description={t(K.description)}\n        submitLabel={t(K.submit)}\n        defaultAnswers={{ period: "last_week", metrics: ["revenue", "orders"], format: "pdf" }}\n        questions={[\n          { id: "period", title: t(K.period), kind: "single", isRequired: true, options: periods },\n          {\n            id: "metrics",\n            title: t(K.metrics),\n            kind: "multiple",\n            isRequired: true,\n            options: [\n              { value: "revenue", label: t(K.revenue) },\n              { value: "orders", label: t(K.orders) },\n              { value: "returns", label: t(K.returns) },\n              { value: "basket", label: t(K.basket) },\n            ],\n          },\n          {\n            id: "format",\n            title: t(K.format),\n            kind: "single",\n            options: [\n              { value: "pdf", label: t(K.pdf) },\n              { value: "excel", label: t(K.excel) },\n            ],\n          },\n        ]}\n        onSubmit={(answers) =>\n          setPeriod(periods.find((option) => option.value === answers["period"])?.label ?? null)\n        }\n      />\n      {period === null ? null : <Text tone="muted">{t(K.built, { period })}</Text>}\n    </View>\n  );\n}\n';
